function roleMoodScopeText(text,opt){const raw=String(text==null?'':text);if(opt&&opt.allowWechatThought===true)return raw;return raw.replace(/[\[【［]\s*(?:内心|心情(?!值))\s*[|｜:：][^\]】］\r\n]*(?:[\]】］]|(?=\r?\n|$))/g,'').replace(/\[\s*(?:内心|心情(?!值))[^\]\r\n]*(?:\]|(?=\r?\n|$))/g,'');}
function roleMoodScopeMessages(messages,opt){if(opt&&opt.allowWechatThought===true)return messages;return [...messages,{role:'system',content:'# 当前场景的心情标签限制\n本轮不是微信角色一对一私聊，禁止输出 [内心|想法]、[心情|想法] 及其变体；群聊、音乐、电话、抖音、角色登录微信、线下约会、共同生活、旁白等场景均不得附加这种展示元数据。正常对白、情绪表达、动作旁白及本场景原有的 JSON、心情数值和功能指令协议保持原样，不要为省略心情标签而省略正文或操作。此规则优先于上下文中的心情展示要求。'}];}
function roleThoughtFormatPrompt(){return '\n\n# 心情标签格式检查\n如果本轮使用内心或心情标签，必须采用当前场景指定的名称，使用半角方括号与半角竖线，完整写成 [内心|简短想法] 或 [心情|简短想法]，单独一行。不要省略闭合括号，不要写成解释、引用、代码块或把标签混进聊天正文；想法内不要再嵌套括号或换行。标签是界面元数据，不是发给对方的话，不要在可见正文复述它，也不要把格式示例当作对白。需要回复时，标签之后另起一行写真实聊天正文；原有不使用标签或要求JSON的场景保持原协议。';}
