function lifeNoteModelPrompt(c){if(!c||!lifeNotesAutoOn()||memoryScopeKey()!=='main'||!S.couple||S.couple.cid!==c.id)return'';return '\n\n# 你给'+S.me.name+'记的小本子\n你私下有个小本子，专门记关于'+S.me.name+'的事——你想长久记住、以后还会想起来的那种。比如ta的喜好和习惯、在意或讨厌的东西、正烦心或期待的事、情绪的起落和缘由、你们说定的约定、重要的日子、ta常提起的人。记不记、记哪一条，完全由你自己判断，不用等ta开口；平常聊着聊着，只要出现了你觉得以后还想记得的事，就顺手记一笔。没有新东西就不记，别为了记而记。\n写法：在这次回复的最后单独附一行 [小事簿|简短类型|本轮原话依据|你自己的话写的总结]。类型用你自己的词（喜好、习惯、约定、情绪、在意、纪念日……都行）。依据要能在本轮你们说过的话里找到，只用来防止记错，不会显示；真正存进本子的只有最后那句总结。\n一轮最多记一条。用完整的一句话、你自己的视角写：“我”只能指你（'+(c.remark||c.name)+'），提到ta就用「'+(c.callme||S.me.name)+'」。不要照搬ta的原话，不要写没发生过的事，也不要把你的猜测写成事实。';}
function lifeNoteCandidateValid(c,text,userText,evidence,kind,replyText){const t=String(text||'').trim(),u=String(userText||'').trim(),e=String(evidence||'').trim(),visible=String(replyText||'').replace(/[\[【][^\]】]*[\]】]/g,' ');if(t.length<8||t.length>220||e.length<3||!u)return false;if(/[?？]|\.{3}|…|[\[\]【】]/.test(t))return false;if(/(?:然后|所以|而且|但是|就是|就|把|让|给|因为)[，。；,;]*$/.test(t))return false;const norm=s=>String(s).replace(/[\s，。！？、；：,.!?;:'"「」『』]/g,'');if(norm(u).includes(norm(t))||norm(t)===norm(aboutMeNoteText(u)))return false;if(!norm(u+' '+visible).includes(norm(e)))return false;/* 记什么由角色自己判断；只有“约定”这类仍要分清是谁答应的、以及有没有真的答应，免得把想问的记成已定的。 */const promised=/(?:答应|约定|承诺|说好|保证)/;if(promised.test(t)){if(!promised.test(e))return false;if(/[?？]|能不能|可不可以|能否|希望|要是|如果|(?:没|没有|还没|不曾|并未|不)(?:有)?(?:答应|约定|承诺|说好|保证)/.test(e))return false;const fromUser=norm(u).includes(norm(e)),roleName=String(c&&(c.remark||c.name)||''),roleOwn=/我(?:已经|会|也|就)?(?:答应|承诺|保证)/.test(t)||!!(roleName&&t.includes(roleName)&&/答应|承诺|保证/.test(t));if(/^我(?:已经|会|也|就)?(?:答应|承诺|保证)/.test(e)&&roleOwn===fromUser)return false;}return memoryCandidateGrounded(c,t,e,'');}
function lifeNoteStripModelTags(text){return String(text||'').replace(/[\[【]\s*(?:小事簿|事件簿)\s*[|｜:：]\s*[^\]】]+[\]】]/g,'');}
function lifeNoteReplyDraft(text,c,userText,source){const tags=String(text||'').match(/[\[【]\s*(?:小事簿|事件簿)\s*[|｜:：]\s*[^\]】]+[\]】]/g);return tags&&tags.length?{tags:tags.join('\n'),owner:c,scope:memoryScopeKey(),userText,source,visible:[]}:null;}
function lifeNoteCommitReply(draft,text){if(!draft||getC(draft.owner.id)!==draft.owner||memoryScopeKey()!==draft.scope)return;draft.visible.push(String(text||''));lifeNoteConsumeModelTags(draft.tags+'\n'+draft.visible.join('\n'),draft.owner,draft.userText,draft.source);}
