function lifeNoteConsumeModelTags(text,c,userText,source){const full=String(text||''),tagRe=/[\[【]\s*(?:小事簿|事件簿)\s*[|｜:：]\s*([^\]】]+)[\]】]/g,visible=full.replace(tagRe,'');let taken=false;return full.replace(tagRe,(tag,body)=>{if(taken||!c||!lifeNotesAutoOn()||memoryScopeKey()!=='main'||!S.couple||S.couple.cid!==c.id)return'';const parts=body.split(/[|｜]/).map(x=>x.trim());if(parts.length!==3)return'';const [kind,evidence,v]=parts;if(!lifeNoteCandidateValid(c,v,userText,evidence,kind,visible))return'';const arr=lifeNotes(),key=memoryNorm({text:v,rolePerspective:true}),evidenceKey=memoryNorm({text:evidence,rolePerspective:true});if(lifeNotesForRole(c).some(n=>memoryNorm({text:n.text,rolePerspective:true})===key||n.evidenceKey===evidenceKey&&Date.now()-(n.ts||0)<86400000))return'';arr.unshift({id:uid(),text:v,source:source||'role',tags:[lifeNoteCategoryKey(kind)],recordedKind:kind,ts:Date.now(),roleId:c.id,accountId:memoryScopeKey(),rolePerspective:true,evidenceKey});taken=true;save();return'';});}
function proactiveContinuationContext(c){if(!c)return'';const rows=msgs(c.id)||[],lastUser=rows.reduce((last,m,i)=>m&&m.role==='user'&&m.type!=='sys'?i:last,-1),sent=rows.slice(lastUser+1).filter(m=>m&&m.role==='assistant'&&['text','voice'].includes(m.type)&&m.content).slice(-10);if(!sent.length)return'';return '\n【你在用户上次发言之后已经主动说过的话】\n'+sent.map(m=>(S.settings.timeAware===false?'':fmtDT(m.time||Date.now())+' ')+String(m.content)).join('\n')+'\n本轮从你自己最后说到的位置继续。上面的追问已经问过；用户还没回答并不是新的回答，也不能把它解释成故意躲避。仅时长增加、手机仍满电或位置未变不算新的话题进展，不要换个说法再问同一件事。可以表达新的想法、分享自己的具体日常、自然换话题，或按既有规则不发消息。';}
