function lifeNoteCategoryKey(value){const raw=String(value==null?'':value).trim();if(!raw)return 'life';const k=raw.toLowerCase(),names={情绪:'emotion',心情:'emotion',感受:'emotion',约定:'promise',承诺:'promise',约好:'promise',喜好:'preference',偏好:'preference',喜欢:'preference',喜爱:'preference',爱好:'preference',习惯:'habit',日常习惯:'habit',纪念日:'anniversary',生日:'anniversary',重要日子:'anniversary',在意:'care',愿望:'wish',心愿:'wish',期待:'wish',朋友:'friend',社交:'friend',工作:'work',睡眠:'sleep',身体:'health',健康:'health',家人:'family',家里:'family',金钱:'money',钱:'money',生活:'life',emotion:'emotion',promise:'promise',preference:'preference',habit:'habit',anniversary:'anniversary',care:'care',wish:'wish',friend:'friend',work:'work',sleep:'sleep',health:'health',family:'family',money:'money',life:'life'};return Object.prototype.hasOwnProperty.call(names,k)?names[k]:k==='all'?'custom:all':raw;}
function lifeNoteTags(note){const raw=note&&note.tags;if(Array.isArray(raw))return raw.filter(x=>typeof x==='string'&&x);if(typeof raw==='string')return raw.split(/[，,、|｜\s]+/).map(x=>x.trim()).filter(Boolean);return lifeTopicOf(note&&note.text||'');}
function lifeTopicOf(text){text=''+(text||'');const tags=[];
  [['work',/工作|上班|老板|同事|加班|项目|客户|会议|工资|职场|公司/],['sleep',/熬夜|睡不着|失眠|通宵|困|睡觉|晚睡/],['health',/生病|发烧|胃疼|头疼|疼|不舒服|医院|吃药|姨妈|例假/],['family',/家里|妈妈|爸爸|父母|亲戚|家人/],['friend',/朋友|闺蜜|同学|室友/],['money',/钱|花钱|工资|还款|账单|穷|买不起/],['emotion',/哭|崩溃|难受|委屈|焦虑|压力|害怕|生气|烦|低落|心情不好/]].forEach(x=>{if(x[1].test(text))tags.push(x[0]);});
  return tags;}
function aboutMeNoteText(text){let v=(''+(text||'')).replace(/[\[【]\s*桌宠\s*(?:[|｜:：]\s*)?[^\]】\r\n]{1,16}(?:[\]】]|$)/g,'').replace(/^[\s\[\【]*(?:记住|小事簿)\s*[\|｜:：]?/,'').replace(/[\]\】]\s*$/,'').replace(/\s+/g,' ').trim();if(!v)return '';
  const me=(S.me&&S.me.name)||'ta';v=v.replace(/[「」『』"']/g,'').trim();
  if(!v)return '';
  if(v.indexOf(me)===0)return v;
  if(/^(我|俺|人家|本宝宝)/.test(v)||/[，,。；;]\s*(我|俺|人家|本宝宝)/.test(v)||/你/.test(v)){
    v=v.replace(/我信了/g,me+'相信了对方').replace(/我不生气了/g,me+'气消了一些').replace(/我没有不开心/g,me+'嘴上说没有不开心').replace(/我没事/g,me+'嘴上说没事');
    v=v.replace(/我/g,me).replace(/俺|人家|本宝宝/g,me).replace(/你不用/g,'希望对方不用').replace(/你不要/g,'希望对方不要').replace(/你别/g,'希望对方别').replace(/你不能/g,'希望对方不能').replace(/你/g,'对方');
    return v.slice(0,120);}
  if(/^(把|拿|抱|躲|哭|闹|撒娇|委屈|难受|生气|害怕|想要|不想|喜欢|讨厌|信了|不生气|心里|心里面|下面|身体|胃|头|肚子|姨妈|例假|疼|不舒服)/.test(v))return (me+v).slice(0,120);
  return v.slice(0,120);}
function roleMemoryPerspectiveText(c,text){let v=String(text||'').replace(/^[\s\[\【]*(?:记住|小事簿)\s*[\|｜:：]?/,'').replace(/[\]\】]\s*$/,'').replace(/\s+/g,' ').replace(/[「」『』]/g,'').trim();if(!v)return'';const aliases=[c&&c.remark,c&&c.name].map(x=>String(x||'').trim()).filter(x=>x&&x!=='我').sort((a,b)=>b.length-a.length);for(const alias of [...new Set(aliases)])v=v.split(alias).join('我');return v.slice(0,220);}
